<p><span style="font-size: 18pt; font-family: 'times new roman', times, serif;"><strong>Deadline for Hispanic Scholarship Fund February 15.&nbsp;</strong></span><strong style="mso-bidi-font-weight: normal;"><span style="font-family: 'Times New Roman',serif;">&nbsp;</span></strong><span style="font-family: 'Times New Roman',serif;">The</span><strong style="mso-bidi-font-weight: normal;"><span style="font-family: 'Times New Roman',serif;"> </span></strong><span style="font-family: 'Times New Roman',serif; mso-bidi-font-weight: bold;">HSF &ldquo;Empowering Courageous Leaders&rdquo;</span><strong style="mso-bidi-font-weight: normal;"><span style="font-family: 'Times New Roman',serif;"> </span></strong><span style="font-family: 'Times New Roman',serif; mso-bidi-font-weight: bold;">Scholarship Program applications are due February 15. <span style="mso-spacerun: yes;">&nbsp;</span>HSF Selects 10,000 outstanding students as HSF Scholars with $30 million in scholarships annually ranging from $500 to $5,000. It also assists with internships and full-time job opportunities. Minimum 3.0 GPA for high school students. <span style="text-decoration: underline;">See, www.hsf.net.</span></span></p>

