<h4 class="\" style="text-align: left;"><strong><span style="font-size: 14pt;">December 1 is Opening Day for FAFSA Rollout. </span><a href="https://www.wjla.com/news/local/fafsa-applications-student-help-free-application-federal-student-aid-december-october-tax-w2-return-income-aid-loans-grants-financial-situation-need-based-assistance-deadlines-college-high-school">https://</a></strong><a href="https://www.wjla.com/news/local/fafsa-applications-student-help-free-application-federal-student-aid-december-october-tax-w2-return-income-aid-loans-grants-financial-situation-need-based-assistance-deadlines-college-high-school">www.wjla.com/news/local/fafsa-applications-student-help-free-application-federal-student-aid-december-october-tax-w2-return-income-aid-loans-grants-financial-situation-need-based-assistance-deadlines-college-high-school</a></h4>

<p><span style="font-size: 18pt; font-family: 'times new roman', times, serif;"><strong>UPDATES ON THE FAFSA ROLLOUT:&nbsp;</strong></span></p>

<p style="text-align: left;"><span style="font-size: 18pt; font-family: 'times new roman', times, serif;"><strong>The FAFSA is now Available.&nbsp;</strong></span><a href="https://studentaid.gov/h/apply-for-aid/fafsa"><span style="font-size: 18pt; font-family: 'times new roman', times, serif;"><strong>https://studentaid.gov/h/apply-for-aid/fafsa</strong></span></a></p>

