<h4 style="text-align: left; line-height: 1;"><span style="font-size: 18pt; font-family: 'times new roman', times, serif;"><strong>U.S. Dept. of Ed Announces FAFSA Corrections Will Not be Available Mid-August as Previously Scheduled. </strong></span><span style="font-size: 10pt;"><a href="https://fsapartners.ed.gov/knowledge-center/library/electronic-announcements/2024-07-30/update-batch-corrections-institutions-electronic-data-exchange-flexibilities-and-additional-support-2024-25-fafsa-cycle?utm_source=Inside+Higher+Ed&amp;utm_campaign=e78a267331-AdmissionsInsider_COPY_01&amp;utm_medium=email&amp;utm_term=0_1fcbc04421-e78a267331-200113909&amp;mc_cid=e78a267331&amp;mc_eid=3d0b2dbd6d"><span style="font-family: 'times new roman', times, serif;"><strong>https://fsapartners.ed.gov/knowledge-center/library/electronic-announcements/2024-07-30/update-batch-corrections-institutions-electronic-data-exchange-flexibilities-and-additional-support-2024-25-fafsa-cycle?utm_source=Inside+Higher+Ed&amp;utm_campaign=e78a267331-AdmissionsInsider_COPY_01&amp;utm_medium=email&amp;utm_term=0_1fcbc04421-e78a267331-200113909&amp;mc_cid=e78a267331&amp;mc_eid=3d0b2dbd6d</strong></span></a></span></h4>

<h4 style="text-align: left; line-height: 1;"><span style="font-size: 18pt; font-family: 'times new roman', times, serif;"><strong>FAFSA Corrections Could Take Longer Than First Thought. </strong></span><a href="https://mail.aol.com/d/list/referrer=newMail&amp;folders=1&amp;accountIds=1&amp;listFilter=NEWMAIL/messages/AEcWyssNx9LrZrC7agfESB_PDl8"><span style="font-size: 12pt; font-family: 'times new roman', times, serif;"><strong>https://mail.aol.com/d/list/referrer=newMail&amp;folders=1&amp;accountIds=1&amp;listFilter=NEWMAIL/messages/AEcWyssNx9LrZrC7agfESB_PDl8</strong></span></a></h4>

<p style="text-align: left; line-height: 1;"><span style="font-size: 18pt; font-family: 'times new roman', times, serif;"><strong>FAFSA Disbursements Could Still Face Further Delays.&nbsp;</strong></span><a href="https://www.nasfaa.org/eds_latest_fafsa_misstep_may_mean_further_delayed_aid_to_college_students"><span style="font-size: 12pt; font-family: 'times new roman', times, serif;"><strong><span style="font-size: 12pt;">https://www.nasfaa.org/</span>eds_latest_fafsa_misstep_may_mean_further_delayed_aid_to_college_students</strong></span></a></p>

