<h4 style="text-align: left; line-height: 1;"><span style="font-size: 18pt; font-family: 'times new roman', times, serif;"><strong><span style="font-size: 14pt;">According to NBC, "44 Percent of Students Said Their College Decisions Came Down to $5,000 in Aid."</span>&nbsp; </strong></span><span style="font-size: 12pt;"><a href="https://www.nbcnewyork.com/news/business/money-report/fafsa-issues-force-hard-choices-44-of-students-said-college-decisions-came-down-to-5000-in-aid/5560606/"><span style="font-family: 'times new roman', times, serif;"><strong>https://www.nbcnewyork.com/news/business/money-report/fafsa-issues-force-hard-choices-44-of-students-said-college-decisions-came-down-to-5000-in-aid/5560606/</strong></span></a></span></h4>

<h3 style="text-align: left; line-height: 1;"><span style="font-size: 14pt; font-family: 'times new roman', times, serif;"><strong>"Federal Student Aid Still Up in the Air for Many," Accordsing to National Public Radio Jne 21. &nbsp; </strong></span><span style="font-size: 14pt; font-family: 'times new roman', times, serif;"><strong><a href="https://www.npr.org/2024/06/19/1198912680/federal-student-aid-still-up-in-the-air-for-many"><span style="font-size: 12pt;">https://www.npr.org/2024/06/19/1198912680/federal-student-aid-still-up-in-the-air-for-many</span></a><br></strong></span></h3>

<h3 style="text-align: left; line-height: 1;"><span style="font-size: 14pt; font-family: 'times new roman', times, serif;"><strong>Students Now May Need to Verify FAFSA Information, According to Wisconsin State Journal June 13.&nbsp;</strong></span><a href="https://www.state-journal.com/education/college-bound-students-may-need-to-verify-information-on-fafsa/article_3eaae1ae-298f-11ef-a182-97d19a5ae8ec.html"><span style="font-size: 12pt; font-family: 'times new roman', times, serif;">https://www.state-journal.com/education/college-bound-students-may-need-to-verify-information-on-fafsa/article_3eaae1ae-298f-11ef-a182-97d19a5ae8ec.html</span></a></h3>

<h3 style="text-align: left; line-height: 1;"><span style="font-size: 18pt; font-family: 'times new roman', times, serif;"><strong><span style="font-size: 14pt;">"Their Financial Aid was in Limbo. How did they Decide?" </span><em><span style="font-size: 14pt;">The Christian Science Monitor.</span>&nbsp;</em></strong></span><span style="font-size: 14pt;"><a href="https://www.csmonitor.com/USA/Education/2024/0522/student-fafsa-decision-financial-aid"><span style="font-family: 'times new roman', times, serif;"><strong>https://www.csmonitor.com/USA/Education/2024/0522/student-fafsa-decision-financial-aid</strong></span></a></span></h3>

<h2 style="text-align: left; line-height: 1;"><span style="font-size: 18pt; font-family: 'times new roman', times, serif;"><strong><span style="font-size: 14pt;">National Decision Day Passes With Many Students in the Dark About Their FAFSA Results. &nbsp; </span><a href="https://www.nbcnews.com/news/education/college-decision-day-passes-many-students-fafsa-delays-linger-rcna150025"><span style="font-size: 12pt;">https://www.nbcnews.com/news/education/college-decision-day-passes-many-students-fafsa-delays-linger-rcna150025</span></a></strong></span></h2>

