<p class="MsoNormal" align="left"><span style="font-family: Times New Roman; font-size: small;"><strong><span style="font-size: large;">Students Face Challenges Applying to College During the Pandemic.</span></strong></span><a class="" href="https://news.wttw.com/2020/12/20/covid-19-and-higher-ed-students-face-challenges-applying-paying-college" target="" name=""><span style="font-size: large;"><span style="font-family: Times New Roman;"><strong> </strong></span></span>https://news.wttw.com/2020/12/20/covid-19-and-higher-ed-students-face-challenges-applying-paying-college </a></p>

<p class="MsoNormal" align="left"><span style="font-size: large;"><span style="font-family: Times New Roman;"><strong><em>Forbes</em> Releases New List of Colleges with ED II&nbsp; </strong><span style="font-size: small;">https://www.forbes.com/sites/kristenmoon/2020/12/14/new-ed-ii-colleges-have-been-added-for-the-2021-cycle-heres-the-complete-list/?sh=9f88cf296e5a</span></span></span><span style="font-family: Times New Roman; font-size: small;"><br></span></p>

<p class="MsoNormal" align="left"><span style="font-family: Times New Roman; font-size: small;"><span style="font-family: Times New Roman;"><span style="font-size: large;"><strong>"60 Minutes" Takes a Look at the Impact of the Pandemic on College Sports. Sunday, December 6. </strong><span style="font-size: small;">https://www.cbsnews.com/news/college-sports-cuts-gymnastics-swimming-pandemic-60-minutes-2020-12-06/</span><strong><br></strong></span></span></span></p>

<p class="MsoNormal" align="left"><span style="font-family: Times New Roman; font-size: small;"><span style="font-family: Times New Roman;"><span style="font-size: large;"><strong>"What's New on the FAFSA This Year." From <em>U.S. News and World Report. </em><span style="font-size: small;">https://www.usnews.com/education/best-colleges/paying-for-college/articles/whats-new-on-the-fafsa-this-year</span><br></strong></span></span></span></p>

<p class="MsoNormal" align="left"><span style="font-family: Times New Roman; font-size: small;"><span style="font-family: Times New Roman;"><span style="font-size: large;"><strong>The New<em> Free Application for Federal Student Aid</em> (FAFSA) for 2021-2022 is Now Available. Click Link Below for&nbsp; Info.&nbsp; <span style="font-size: small;"><a class="" href="https://studentaid.gov/h/apply-for-aid/fafsa" target="" name="">https://studentaid.gov/h/apply-for-aid/fafsa </a></span><br></strong></span></span></span></p>

<p class="MsoNormal" align="left"><span style="font-family: Times New Roman; font-size: small;"><span style="font-family: Times New Roman;"><span style="font-size: large;"><strong>Low-Income Students Dropping Out of College, Often Due to a Lack of the Technology Needed for On-Line Courses. From the <em>Washington Post. </em></strong></span></span></span><a class="" href="https://www.washingtonpost.com/business/2020/09/16/college-enrollment-down/" target="" name="">https://www.washingtonpost.com/business/2020/09/16/college-enrollment-down/ </a></p>

<p class="MsoNormal" align="left"><span style="font-family: Times New Roman; font-size: small;"><span style="font-family: Times New Roman;"><span style="font-size: large;"><strong>U.S. News Releases its Annual College Rankings--with a Few Caveats. <span style="font-size: small;"><a class="" href="https://www.usnews.com/education/blogs/college-rankings-blog/articles/2020-09-14/key-changes-in-how-the-2021-best-colleges-rankings-were-calculated" target="" name="">https://www.usnews.com/education/blogs/college-rankings-blog/articles/2020-09-14/key-changes-in-how-the-2021-best-colleges-rankings-were-calculated</a></span><br></strong></span></span></span></p>

<p class="MsoNormal" align="left"><span style="font-family: Times New Roman; font-size: small;"><span style="font-family: Times New Roman;"><span style="font-size: large;"><strong>UPDATES: No sooner had the August/September Issue of COLLEGE BOUND announced those universities opening face-to-face, than some announced they were hitting "pause" due to outbreaks of COVID-19.&nbsp; <br></strong></span></span></span></p>

