<div align="left"><span style="font-family: Times New Roman; font-size: large;"><strong>What Will Colleges Do Come Fall? Two Universities Are Taking Different Approaches. A <em>Chronicle of Higher Education</em> Article. <br></strong></span></div>

<div align="left">&nbsp;</div>

