<p class="MsoNormal" align="left"><span style="font-family: Times New Roman; font-size: large;"><strong><em>People are Talking About...</em>Commencement Speaker at Morehouse College Commencement Pledges to Pay all Graduates' Student Loans. See, <em>USA. Today</em>. <br></strong></span></p>

<p class="MsoNormal" align="left"><span style="font-family: Times New Roman; font-size: large;"><strong>"How to Decipher Those College Financial Aid Offers," from <em>The Los Angeles Times. </em></strong><span style="font-size: medium;">See,</span><span style="font-size: small;"><strong> </strong></span><span style="font-size: medium;"><span style="font-size: small;"><a class="" href="https://www.latimes.com/business/la-fi-financial-aid-offers-20190512-story.html" target="" name="">https://www.latimes.com/business/la-fi-financial-aid-offers-20190512-story.html</a><br></span></span></span></p>

<p class="MsoNormal" align="left">&nbsp;</p>

<p class="MsoNormal" align="left"><span style="font-family: Times New Roman; font-size: large;"><strong>Ivy League Results for Class of 2023. </strong>As <em>COLLEGE BOUND</em>'s April Issue goes to press, colleges and universities are just starting to post their admissions results. Here, in <em>CB'</em>s "Admissions Story-of-the-Day" are the Ivy league admit stats (hot off the press) with links to the announcements directly from the schools. (See <em>CB'</em>s April issue for other school's reports.) <br></span></p>

<p class="MsoNormal" align="left"><span style="font-family: Times New Roman; font-size: large;"><strong>Brown U</strong>. Brown states its Brown Promise initiative, replacing loans with scholarship funds, played a role in its attracting its largest applicant pool in history. It admitted 2,551 students from 38, 674 applicants. <span style="font-size: small;">See, <a class="" href="https://brown.edu/articles/2018/03/admission." target="" name="">https://brown.edu/articles/2018/03/admission.</a></span> <br></span></p>

<p class="MsoNormal" align="left"><span style="font-family: Times New Roman; font-size: large;"><strong>Columbia (University) C.</strong> Columbia and the School of Engineering and Applied Sciences accepted but 5.1 percent of applicants from a record number, 42,569. Acceptance rates have been declining for the last five years and 2,190 students were admitted for the Class of 2023. See,&nbsp;<span style="font-size: small;"> https://www.columbiaspectator.com/news/2019/03/28/ </span><br></span></p>

<p class="MsoNormal" align="left"><span style="font-family: Times New Roman; font-size: large;"><strong>Cornell U.</strong> The Class of 2023 at Cornell is the "most diverse" in its history. It admitted 5,183 students from 49,000 applications for an admit rate of 10.6 percent. Fifty-five percent of admitted students identify as students of color including underrepresented minorities and Asian students. See, <span style="font-size: small;"><a class="" href="news.cornell.edu/stories/2019/03/ ." target="" name="">news.co</a></span></span><span style="font-family: Times New Roman; font-size: large;"><span style="font-size: small;">rnell.edu/stories/2019/03/ </span>.</span></p>

<p class="MsoNormal" align="left"><span style="font-family: Times New Roman; font-size: large;"><strong>Dartmouth C.</strong> Dartmouth's acceptance rate declined for the third year in a row with 7.9 percent of the 28,650 applicants accepted. A record 16 percent of the Class of 2023 are first-generation students. About 40 percent come from low- or middle-income families. Nine percent are legacies. See, <span style="font-size: small;"><a class="" href="http://www.thedartmouth.com/article/s019/03/ ." target="" name="">www.thedartmouth.com/article/s019/03/ .</a></span></span></p>

<p class="MsoNormal" align="left"><span style="font-family: Times New Roman; font-size: large;"><strong>Harvard U.</strong> Regular-action decisions were sent to 1,950 students March 28. The Class of 2023 admits come from 89 countries and all states. International citizens comprise 12.3 percent of the class. See, <a class="" href="http://www.harvard.edu/gazette/story/2019/03/." target="" name="">http://www.harvard.edu/gazette/story/2019/03/. </a><br></span></p>

<p class="MsoNormal" align="left"><span style="font-family: Times New Roman; font-size: large;"><strong>Princeton U. </strong>Princeton admitted 1,895 students for the Class of 2023, selected from 32,804 applications representing 10,813 high schools and 161 countries. Of those admitted, 52 percent are women, 48 percent men and 63 percent some from public high schools. See, <a class="" href="https://www.princeton.edu/news/2019/03/28/ ." target="" name=""><span style="font-size: small;">https://www.princeton.edu/news/2019/03/28/</span> . </a><br></span></p>

<p class="MsoNormal" align="left"><span style="font-family: Times New Roman; font-size: large;"><span style="font-family: Times New Roman; font-size: large;"><strong>The U. of Pennsylvania. </strong></span>Penn admitted 3,345 students to its 267th class from a pool of 44,960 applicants. The middle 50 percent testing ranges from 1460-1550 on the SAT and 33-35 on the ACT. the university meets 100 percent of demonstrated need for four years with grants and work-study. <span style="font-size: small;"><span style="font-size: large;">See</span>, <a class="" href="https:penntoday.upenn.edu/news/university-pennsylvania-regular-decision-results-class-2023." target="" name="">https:penntoday.upenn.edu/news/university-pennsylvania-regular-decision-results-class-2023. </a><br></span></span></p>

<p class="MsoNormal" align="left"><span style="font-family: Times New Roman; font-size: large;"><strong>Yale U. </strong>For the last two years, Yale has expanded the size of its first-year class. The Class of 2023 will be 15 percent larger than the previous classes with 2,178 students admitted from 36,843 applicants.This year's group of admitted students includes more students receiving federal Pell Grants than any in Yale's history. See,</span><a class="" href="http://news.yale.edu/2019/03/28/yale-college-admits-2178-students-third-years-expanded-class-size." target="" name=""><span style="font-size: large;"><span style="font-family: Times New Roman;"> </span></span>http://news.yale.edu/2019/03/28/yale-college-admits-2178-students-third-years-expanded-class-size. </a></p>

