<h3 class="\" align="left"><span style="font-family: Times New Roman; font-size: large;">See, https:www.usnews.com/education/best-high-schools . </span><span style="font-family: Times New Roman; font-size: large;"><br></span></h3>

<h3 class="\" align="left"><span style="font-family: Times New Roman; font-size: large;">&nbsp;</span></h3>

<h3 class="\" align="left"><span style="font-family: Times New Roman; font-size: large;"><strong>Admissions Results from the Ivy League.</strong> Below are the Headlines From \r\nthe Colleges in the Ivy League, with the Web Links to the Schools. (See \r\nCOLLEGE BOUND\'S April Issue for More Stats and Decisions from Other \r\nColleges.) <br></span></h3>

<p align="left"><span style="font-family: Times New Roman; font-size: large;">&nbsp;&nbsp;&nbsp;&nbsp; <strong>Brown Admits But 8.3 percent</strong>.\r\n Brown University in Providence attracted 32,724 applications for the \r\nClass of 2021, an increase from last year\'s 32,280, and an all time \r\nhigh. Brown admitted 2,722 students from that pool, including 695 who \r\nwere admitted Early Decision, for an admit rate of 8.3 percent. Students\r\n in the admitted class come from all 50 states and 77 nations around the\r\n world. See, www.brown.edu. <br></span></p>

<p align="left"><span style="font-family: Times New Roman; font-size: large;">&nbsp; &nbsp; <strong>Columbia U. Had Largest Applicant Pool in Its History.</strong>\r\n The Office of Undergraduate Admissions at Columbia University in New \r\nYork City received 37,389 applications for its Class of 2021, a 3 \r\npercent increase from last year. The admit rate for Columbia College and\r\n the School of Engineering and Applied Science was 5.8 percent this \r\nyear, down from 6 percent last year. See, www.columbia.edu. &nbsp;&nbsp;&nbsp; <strong><br></strong></span></p>

<p align="left"><span style="font-family: Times New Roman; font-size: large;"><strong>&nbsp;&nbsp;&nbsp; Cornell Places 5,713 Students on Its Wait List</strong>.\r\n Cornell University in New York received 47,038 applications for its \r\nClass of 2021, the most in school history. Cornell admitted 5,889 \r\nstudents from the pool and placed 5,713 students on its wait list. Over \r\n30 percent of the new class self identified as underrepresented \r\nminorities. See, wwww.cornell.edu. <br></span></p>

<p align="left"><span style="font-family: Times New Roman; font-size: large;">&nbsp;&nbsp;&nbsp;&nbsp; <strong>Dartmouth Accepted 43 percent of its Class Early</strong>.\r\n Dartmouth College in New Hampshire received 20,021 applications from \r\nits Class of 2021, a decrease of 3.2 percent from last year, and offered\r\n admissions to 2,092 students. Early Decision applications reached \r\n1,999, a 3.7 percent increase over last year. Of those, 555 students \r\nwere accepted early, and represent 47 percent of the new class. See, \r\nwww.dartmouth.edu. <br></span></p>

<p align="left"><span style="font-family: Times New Roman; font-size: large;">&nbsp;&nbsp;&nbsp;&nbsp; <strong>Harvard Admits 5.2 Percent</strong>.\r\n Harvard College received a record 39,506 applications this year, up 1 \r\npercent from last year. It admitted 2,056 students, including 938 \r\naccepted last December under its Early Action Program. Just over 15 \r\npercent of the admitted students are the first in their families to go \r\nto college. See, harvard.edu. <br></span></p>

<p align="left"><span style="font-family: Times New Roman; font-size: large;">&nbsp;&nbsp;&nbsp;&nbsp; <strong>Penn Admits 9.1 Percent While Announcing it is Increasing its Financial Aid</strong>.\r\n The University of Pennsylvania fielded 40,413 applications to the Class\r\n of 2021 and admitted 3,699 of them, a record low 9.15 percent. Penn \r\nalso announced that it is increasing its financial aid budget by $9.4 \r\nmillion. See, www.penn.edu. <br></span></p>

<p align="left"><span style="font-family: Times New Roman; font-size: large;">&nbsp;&nbsp;&nbsp;&nbsp; <strong>Princeton Admits 6.1 Percent.</strong>\r\n Princeton University in New Jersey received 31,056 applications and \r\noffered admission to 1,890 students, for an admit rate of 6.1 percent. \r\nSome 770 of the 1,890 offers were extended in December as part of \r\nPrinceton\'s single choice Early Action process. See, www.princeton.edu.</span></p>

<p align="left"><span style="font-family: Times New Roman; font-size: large;">&nbsp;&nbsp;&nbsp;&nbsp; <strong>Yale\'s Largest Class Ever</strong>.\r\n Yale University in Connecticut attracted 32,900 applications. Yale \r\noffered admissions to 2,272 of the students. The incoming freshman class\r\n is scheduled to be the largest class in school history with 1,550 \r\nstudents, 15 percent larger than recent classes. See, www.yale.edu. <br></span></p>

